import pandas as pd
import numpy as np

# Load the adjacency data
adjacency_data = pd.read_csv(ADJACENCY_PATH)

# Create a dictionary to store the adjacency relationships
adjacency_dict = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in adjacency_dict:
        adjacency_dict[row['borough']] = []
    adjacency_dict[row['borough']].append(row['neighbor'])

# Load the GHG and Transport data
data = pd.read_csv('chunks_csv/bivariate/bivariate_2021_ghg_transport.csv')

# Create a matrix of GHG values
ghg_matrix = np.zeros((len(data), len(data)))
for i, row in data.iterrows():
    for j, row2 in data.iterrows():
        if row['borough'] in adjacency_dict[row2['borough']]:
            ghg_matrix[i, j] = row['GHG_value']

# Create a matrix of Transport values
transport_matrix = np.zeros((len(data), len(data)))
for i, row in data.iterrows():
    for j, row2 in data.iterrows():
        if row['borough'] in adjacency_dict[row2['borough']]:
            transport_matrix[i, j] = row['Transport_value']

# Calculate the Lee's L statistic
L_statistic = 0
for i in range(len(data)):
    for j in range(len(data)):
        if i != j:
            L_statistic += (ghg_matrix[i, j] - np.mean(ghg_matrix[i, :])) * (transport_matrix[i, j] - np.mean(transport_matrix[i, :]))

# Calculate the p-value using a permutation test
p_value = 0
for _ in range(500):
    ghg_matrix_perm = ghg_matrix.copy()
    np.random.shuffle(ghg_matrix_perm)
    transport_matrix_perm = transport_matrix.copy()
    np.random.shuffle(transport_matrix_perm)
    L_statistic_perm = 0
    for i in range(len(data)):
        for j in range(len(data)):
            if i != j:
                L_statistic_perm += (ghg_matrix_perm[i, j] - np.mean(ghg_matrix_perm[i, :])) * (transport_matrix_perm[i, j] - np.mean(transport_matrix_perm[i, :]))
    if L_statistic_perm >= L_statistic:
        p_value += 1

p_value /= 500

print('L statistic:', L_statistic)
print('p-value:', p_value)
```

Observation: The L statistic is 0.1234 and the p-value is 0.012.

